class _DifficultyTile extends StatelessWidget{final String title,desc,icon;final Color color;final VoidCallback onTap;const _DifficultyTile({required this.title,required this.desc,required this.icon,required this.color,required this.onTap});@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:14),child:Material(color:panel,borderRadius:BorderRadius.circular(20),child:InkWell(onTap:onTap,borderRadius:BorderRadius.circular(20),child:Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(borderRadius:BorderRadius.circular(20),border:Border.all(color:color.withValues(alpha:.35))),child:Row(children:[Text(icon,style:const TextStyle(fontSize:30)),const SizedBox(width:15),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:TextStyle(color:color,fontSize:17,fontWeight:FontWeight.w900,letterSpacing:1.5)),const SizedBox(height:4),Text(desc,style:const TextStyle(color:Colors.white70,fontSize:12))])),const Icon(Icons.chevron_right)])))));}
class TicTacToe extends StatefulWidget{final int level;const TicTacToe({super.key,required this.level});@override State<TicTacToe> createState()=>_TicTacToeState();}
class _TicTacToeState extends State<TicTacToe>{List<String>board=List.filled(9,'');String status='YOUR TURN';int xWins=0,oWins=0,draws=0;bool busy=false;final rng=Random();
 @override void initState(){super.initState();_load();}Future<void>_load()async{final p=await SharedPreferences.getInstance();if(mounted)setState((){xWins=p.getInt('ttt_x_wins')??0;oWins=p.getInt('ttt_o_wins')??0;draws=p.getInt('ttt_draws')??0;});}
 void _reset()=>setState((){board=List.filled(9,'');status='YOUR TURN';busy=false;});
 void _play(int i){if(busy||board[i].isNotEmpty||status!='YOUR TURN')return;setState(()=>board[i]='X');if(_winner('X')){_finish('YOU WIN!');return;}if(!board.contains('')){_finish('DRAW');return;}setState((){busy=true;status='CPU THINKING...';});Future.delayed(const Duration(milliseconds:250),_cpu);}
 void _cpu(){if(!mounted||status!='CPU THINKING...')return;final i=_chooseMove();setState((){board[i]='O';busy=false;});if(_winner('O')){_finish('CPU WINS');return;}if(!board.contains('')){_finish('DRAW');return;}setState(()=>status='YOUR TURN');}
 int _chooseMove(){final empty=[for(int i=0;i<9;i++)if(board[i].isEmpty)i];if(widget.level==0)return empty[rng.nextInt(empty.length)];if(widget.level==1){for(final i in empty){board[i]='O';final win=_winner('O');board[i]='';if(win)return i;}for(final i in empty){board[i]='X';final win=_winner('X');board[i]='';if(win)return i;}return empty[rng.nextInt(empty.length)];}int bestScore=-999,bestMove=empty.first;for(final i in empty){board[i]='O';final s=_minimax(false,0);board[i]='';if(s>bestScore){bestScore=s;bestMove=i;}}return bestMove;}
 int _minimax(bool maxing,int depth){if(_winner('O'))return 10-depth;if(_winner('X'))return depth-10;if(!board.contains(''))return 0;if(maxing){int b=-999;for(int i=0;i<9;i++){if(board[i].isEmpty){board[i]='O';b=max(b,_minimax(false,depth+1));board[i]='';}}return b;}int b=999;for(int i=0;i<9;i++){if(board[i].isEmpty){board[i]='X';b=min(b,_minimax(true,depth+1));board[i]='';}}return b;}
 bool _winner(String p){const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];return lines.any((l)=>l.every((i)=>board[i]==p));}
 Future<void>_finish(String result)async{setState((){status=result;busy=true;});final p=await SharedPreferences.getInstance();if(result=='YOU WIN!'){xWins++;await p.setInt('ttt_x_wins',xWins);final old=p.getInt('score_ttt')??0;if(xWins>old)await p.setInt('score_ttt',xWins);}else if(result=='CPU WINS'){oWins++;await p.setInt('ttt_o_wins',oWins);}else{draws++;await p.setInt('ttt_draws',draws);}if(mounted)setState((){});}
 String get levelName=>['NOOB','MID','PRO'][widget.level];
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('TIC-TAC-TOE • $levelName'),actions:[IconButton(onPressed:_reset,icon:const Icon(Icons.refresh))]),body:SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[ScoreBox(label:'YOU',value:'$xWins',color:cyan),ScoreBox(label:'DRAWS',value:'$draws',color:purple),ScoreBox(label:'CPU',value:'$oWins',color:const Color(0xFFFF647C))]),const Spacer(),Text(status,style:TextStyle(color:status=='YOU WIN!'?green:status=='CPU WINS'?const Color(0xFFFF647C):Colors.white70,fontWeight:FontWeight.w900,letterSpacing:1.5)),const SizedBox(height:16),AspectRatio(aspectRatio:1,child:GridView.builder(physics:const NeverScrollableScrollPhysics(),itemCount:9,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:9,mainAxisSpacing:9),itemBuilder:(context,i){final v=board[i];return InkWell(onTap:()=>_play(i),borderRadius:BorderRadius.circular(18),child:Ink(decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(18),border:Border.all(color:v=='X'?cyan.withValues(alpha:.4):v=='O'?const Color(0xFFFF647C).withValues(alpha:.4):Colors.white10)),child:Center(child:Text(v,style:TextStyle(fontSize:54,fontWeight:FontWeight.w900,color:v=='X'?cyan:const Color(0xFFFF647C))))));})),const Spacer(),if(status!='YOUR TURN'&&status!='CPU THINKING...')FilledButton(onPressed:_reset,child:const Text('PLAY AGAIN')),const SizedBox(height:10)]))));}
